// Content with portions generated by generative AI platform
package org.eclipse.kura.rest.provider.test.jwt;

import static org.junit.Assert.assertEquals;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.eclipse.kura.rest.provider.test.util.AbstractJwtRestScenario;
import org.junit.Test;

public class RefreshTokenReplayTest extends AbstractJwtRestScenario {

    private final List<Integer> exchangeStatuses = new ArrayList<>();
    private String ownerRefreshToken;
    private String attackerRefreshToken;

    @Test
    public void replayingAStolenRefreshTokenRevokesItsWholeFamily() throws Exception {
        givenAnIdentityWithPermissions(ASSETS_PERMISSION);
        givenTheOwnerLoggedIn();
        givenTheAttackerExchanged(this.ownerRefreshToken);

        whenTheOwnerExchanges(this.ownerRefreshToken);
        whenTheAttackerExchanges(this.attackerRefreshToken);

        thenTheExchangeStatusesAre(200, 401, 401);
    }

    /*
     * The verifier accepts expired tokens within its clock skew tolerance (30 seconds by default), so a refresh token
     * family stays tracked for the configured retention after its latest refresh token expires.
     */
    @Test
    public void theLatestRefreshTokenStaysUsableForTheRetentionAfterItsExpiry() throws Exception {
        givenTheRestServiceProperties(Map.of(REFRESH_TOKEN_DURATION, 1, USED_REFRESH_TOKEN_RETENTION, 60));
        givenAnIdentityWithPermissions(ASSETS_PERMISSION);
        givenATokenPairIssuedToTheIdentity();
        givenTheRefreshTokenWasExchangedWithStatus(200);
        givenTimePasses(Duration.ofSeconds(2));

        whenTheRefreshEndpointReceives(theRefreshToken());

        thenATokenPairIsReturned();
    }

    private void givenTheOwnerLoggedIn() {
        givenATokenPairIssuedToTheIdentity();

        this.ownerRefreshToken = theRefreshToken();
    }

    private void givenTheAttackerExchanged(final String refreshToken) {
        this.attackerRefreshToken = exchange(refreshToken).orElse(this.attackerRefreshToken);
    }

    private void whenTheOwnerExchanges(final String refreshToken) {
        this.ownerRefreshToken = exchange(refreshToken).orElse(this.ownerRefreshToken);
    }

    private void whenTheAttackerExchanges(final String refreshToken) {
        this.attackerRefreshToken = exchange(refreshToken).orElse(this.attackerRefreshToken);
    }

    private void thenTheExchangeStatusesAre(final Integer... statuses) {
        assertEquals(List.of(statuses), this.exchangeStatuses);
    }

    private Optional<String> exchange(final String refreshToken) {
        whenTheRefreshEndpointReceives(refreshToken);

        final int status = expectResponse().getStatus();
        this.exchangeStatuses.add(status);

        if (status != 200) {
            return Optional.empty();
        }

        thenATokenPairIsReturned();
        return Optional.of(theRefreshToken());
    }
}
